  dist1 <- define_surv_param('exp', rate = 0.05)
  
  # Roundtrip: surv_prob(dist, surv_quantile(dist, p)) ~ p
  probs <- c(0.9, 0.5, 0.1)
  times <- surv_quantile(dist1, probs)
  expect_equal(surv_prob(dist1, times), probs, tolerance = 1e-6)
  
